    "site.admin.staff.roleNote.doctor": "Full clinical workflow: queue, EMR, orders, prescriptions, own patients.",
    "site.admin.staff.roleNote.nurse": "Runs the queue at the desk, records vitals, gives medicines at the bedside (eMAR). No prescribing.",
    "site.admin.staff.roleNote.reception": "Registers and checks in patients, assigns to a doctor. Reads the chart, cannot edit it.",
    "site.admin.staff.roleNote.pharmacy": "Reads and dispenses medication orders, verifies an order against the chart. No consultation notes.",
    "site.admin.staff.roleNote.lab": "Sees ordered tests and releases results. No other chart access.",
    "site.admin.staff.roleNote.billing": "Reads charges, invoices and claims. Cannot take payment (see Cashier for that).",
    "site.admin.staff.roleNote.him": "Reads the chart to decide and record release-of-information requests.",
    "site.admin.staff.roleNote.bloodBank": "Crossmatches, issues and administers transfusions only.",
    "site.admin.staff.roleNote.radiographer": "Acquires the imaging study. Reads the chart, cannot file a report or protocol a study.",
    "site.admin.staff.roleNote.radiologist": "Protocols and reports imaging studies (the same authority a lab result release uses). No other chart write.",
    "site.admin.staff.roleNote.obstetrician": "A doctor who also keeps the PCPNDT Form F and the MTP register.",
    "site.admin.staff.roleNote.publicHealth": "Public health nodal officer: reads the chart and keeps the notifiable disease register and the weekly IHIP export.",
    "site.admin.staff.roleNote.supervisor": "Runs the OPD queue and reads the chart. Approves stores indents for the departments in their scope.",
    "site.admin.staff.roleNote.storeKeeper": "Runs general stores: items, store locations, issuing approved indents, receiving and ordering. No chart access.",
    "site.admin.staff.roleNote.biomedicalEngineer": "Keeps the asset register, preventive maintenance, calibration and job cards. No chart access.",
