    "site.gov.br.piTitle": "What the patients were told (DPDP Rules 2025 r.7(1), all five)",
    "site.gov.br.bhTitle": "Detailed report to the Board (DPDP Rules 2025 r.7(2)(b))",
    "site.gov.br.law2": "Report a cyber security incident, including a data breach, to CERT-In within 6 hours of noticing it (in force now). From DPDP commencement the Data Protection Board is told without delay and sent a detailed report within 72 hours of becoming aware, and each affected patient is told without delay. There is no 'not notifiable' state: a record is withdrawn only as not a personal data breach, confirmed by a second person. Do not write the breached personal data itself here.",
