    "site.gov.nt.s5b": "Each part below is required before the notice is published: the data item by item, the purposes, withdrawal, the rights, the recipients and the hospital's name and address (DPDP Rules 2025 r.3; SPDI Rules 2011 r.5(3)), and the Data Protection Officer or Grievance Officer contact. Write it in English or a language of the Eighth Schedule. Publishing again makes a new version; patients acknowledge a version. From DPDP commencement, patients given a notice before then need a fresh one (s.5(2)).",
